"""tools/hotel_tools.py — SearchHotels and BookHotel tool implementations."""

from __future__ import annotations

from typing import Any

from pydantic import BaseModel, Field

from optimized_llm_planning_memory.tools.base import BaseTool


class SearchHotelsInput(BaseModel):
    city: str = Field(description="City in which to search for hotels.")
    check_in: str = Field(description="Check-in date (YYYY-MM-DD).")
    check_out: str = Field(description="Check-out date (YYYY-MM-DD).")
    num_guests: int = Field(default=1, ge=1, le=20)


class BookHotelInput(BaseModel):
    hotel_id: str = Field(description="The hotel_id from a prior SearchHotels result.")
    guest_details: dict[str, Any] = Field(default_factory=dict)


class SearchHotels(BaseTool):
    """Search for available hotels in a city for a given stay period."""

    tool_name = "search_hotels"
    tool_description = (
        "Search for available hotels in a city for a given check-in/check-out period. "
        "Returns price per night, star rating, district, and amenities."
    )
    input_schema = SearchHotelsInput

    def _execute(self, validated_input: SearchHotelsInput) -> Any:
        return self._simulator.search_hotels(
            city=validated_input.city,
            check_in=validated_input.check_in,
            check_out=validated_input.check_out,
            num_guests=validated_input.num_guests,
        )

    def _generate_error_feedback(self, error: Exception, arguments: dict[str, Any]) -> str:
        return (
            f"Tool 'search_hotels' failed: {error}. "
            f"Try: verify city='{arguments.get('city')}' is valid and that "
            f"check_in < check_out (both YYYY-MM-DD)."
        )


class BookHotel(BaseTool):
    """Confirm a hotel booking using a hotel_id from a prior search."""

    tool_name = "book_hotel"
    tool_description = (
        "Book a specific hotel using its hotel_id from a prior search_hotels call. "
        "Returns a booking confirmation with a booking_ref."
    )
    input_schema = BookHotelInput

    def _execute(self, validated_input: BookHotelInput) -> Any:
        return self._simulator.book_hotel(
            hotel_id=validated_input.hotel_id,
            guest_details=validated_input.guest_details,
        )

"""tools/activity_tools.py — SearchActivities and BookActivity tool implementations."""

from __future__ import annotations

from typing import Any

from pydantic import BaseModel, Field

from optimized_llm_planning_memory.tools.base import BaseTool


class SearchActivitiesInput(BaseModel):
    city: str = Field(description="City in which to search for activities.")
    date: str = Field(description="Date of the activity (YYYY-MM-DD).")
    category: str | None = Field(
        default=None,
        description="Optional category filter (e.g., 'outdoor', 'museum', 'food', 'nightlife').",
    )


class BookActivityInput(BaseModel):
    activity_id: str = Field(description="The activity_id from a prior SearchActivities result.")
    participant_details: dict[str, Any] = Field(default_factory=dict)


class SearchActivities(BaseTool):
    """Search for available activities in a city on a specific date."""

    tool_name = "search_activities"
    tool_description = (
        "Search for activities available in a city on a specific date. "
        "Optionally filter by category (outdoor, museum, food, nightlife, etc.). "
        "Returns activity name, duration, price, and available capacity."
    )
    input_schema = SearchActivitiesInput

    def _execute(self, validated_input: SearchActivitiesInput) -> Any:
        return self._simulator.search_activities(
            city=validated_input.city,
            date=validated_input.date,
            category=validated_input.category,
        )


class BookActivity(BaseTool):
    """Confirm an activity booking using an activity_id from a prior search."""

    tool_name = "book_activity"
    tool_description = (
        "Book a specific activity using its activity_id from a prior search_activities call. "
        "Returns a booking confirmation with a booking_ref."
    )
    input_schema = BookActivityInput

    def _execute(self, validated_input: BookActivityInput) -> Any:
        return self._simulator.book_activity(
            activity_id=validated_input.activity_id,
            participant_details=validated_input.participant_details,
        )

"""tools/info_tools.py — Read-only world information tools (no bookings)."""

from __future__ import annotations

from typing import Any

from pydantic import BaseModel, Field

from optimized_llm_planning_memory.tools.base import BaseTool


class GetCityInfoInput(BaseModel):
    city: str = Field(description="Name of the city to retrieve information for.")


class GetLocationDetailsInput(BaseModel):
    location_id: str = Field(description="The location_id of a specific node in the city graph.")


class GetEventsInput(BaseModel):
    city: str = Field(description="City in which to look for events.")
    start_date: str = Field(description="Start of the date range (YYYY-MM-DD, inclusive).")
    end_date: str = Field(description="End of the date range (YYYY-MM-DD, inclusive).")


class GetCityInfo(BaseTool):
    """Retrieve city metadata: districts, landmarks, transport hubs, connectivity."""

    tool_name = "get_city_info"
    tool_description = (
        "Get general information about a city: its districts, landmark locations, "
        "airport hubs, and the location graph. Use this to understand city layout "
        "before searching for hotels or activities."
    )
    input_schema = GetCityInfoInput

    def _execute(self, validated_input: GetCityInfoInput) -> Any:
        return self._simulator.get_city_info(city=validated_input.city)


class GetLocationDetails(BaseTool):
    """Retrieve detailed attributes for a specific location node."""

    tool_name = "get_location_details"
    tool_description = (
        "Get detailed attributes for a specific location node (hotel, venue, transport hub, etc.). "
        "Includes accessibility features, nearby nodes, and tags. "
        "Requires a valid location_id from a prior get_city_info or search result."
    )
    input_schema = GetLocationDetailsInput

    def _execute(self, validated_input: GetLocationDetailsInput) -> Any:
        return self._simulator.get_location_details(location_id=validated_input.location_id)


class GetEvents(BaseTool):
    """Retrieve special events occurring in a city within a date range."""

    tool_name = "get_events"
    tool_description = (
        "Get special events (festivals, concerts, exhibitions) in a city "
        "within a start–end date range. Use this to find event-based activities "
        "and plan around them."
    )
    input_schema = GetEventsInput

    def _execute(self, validated_input: GetEventsInput) -> Any:
        return self._simulator.get_events(
            city=validated_input.city,
            start_date=validated_input.start_date,
            end_date=validated_input.end_date,
        )

