def load_requests(requests_dir: Path, split: str = "test") -> list[UserRequest]:
    """Load UserRequest JSON files from data/user_requests/{split}/."""
    if split == "all":
        globs = list(requests_dir.glob("**/*.json"))
    else:
        globs = list((requests_dir / split).glob("*.json"))

    results = []
    for p in sorted(globs):
        try:
            data = json.loads(p.read_text(encoding="utf-8"))
            results.append(UserRequest.model_validate(data))
        except Exception as e:
            print(f"  [skip] {p.name}: {e}")
    return results


def pick_requests(
    all_reqs: list[UserRequest],
    mode: str,
    manual_indices: list[int],
    random_n: int,
) -> list[UserRequest]:
    if mode == "manual":
        return [all_reqs[i] for i in manual_indices if i < len(all_reqs)]
    elif mode == "random":
        return random.sample(all_reqs, min(random_n, len(all_reqs)))
    else:
        raise ValueError(f"Unknown selection mode: {mode}")


# ── Configure ──────────────────────────────────────────────────────────────────
REQUEST_SPLIT   = "test"    # "train" | "test" | "all"
SELECTION_MODE  = "manual"  # "manual" | "random"
MANUAL_INDICES  = [0]       # indices into all_requests (used when mode=="manual")
RANDOM_N        = 3         # N to sample (used when mode=="random")

all_requests = load_requests(REQUESTS_DIR, split=REQUEST_SPLIT)
print(f"Found {len(all_requests)} request(s) in split='{REQUEST_SPLIT}'")
print()
for i, r in enumerate(all_requests):
    print(f"  [{i}] {r.request_id:<35} dest={r.destination_cities}  "
          f"${r.budget_usd:.0f}  {r.start_date} to {r.end_date}")

def load_matching_episodes(episodes_dir: Path, requests: list[UserRequest]):
    """Load pre-existing episodes from disk whose request_id matches selected requests."""
    request_ids = {r.request_id for r in requests}
    all_eps = []

    # Check both standard episodes dir and baseline eval dir
    for search_dir in [episodes_dir, BASELINE_DIR]:
        if search_dir.exists():
            for p in sorted(search_dir.glob("ep_*.json")):
                try:
                    ep = load_episode(p)
                    if ep.request_id in request_ids:
                        all_eps.append(ep)
                except Exception:
                    pass

    # Deduplicate by episode_id, keep last
    seen = {}
    for ep in all_eps:
        seen[ep.episode_id] = ep
    return list(seen.values())


selected_episodes = load_matching_episodes(EPISODES_DIR, selected_requests)
print(f"Loaded {len(selected_episodes)} matching episode(s) from disk.")
for ep in selected_episodes:
    print(f"  {ep.episode_id}  request={ep.request_id}  success={ep.success}  steps={ep.total_steps}")

agg = evaluator.aggregate(eval_results)

# Show mean metrics in a tidy table
mean_rows = {k: v for k, v in agg.items() if k.endswith("_mean")}
std_rows  = {k: v for k, v in agg.items() if k.endswith("_std")}

df_agg = pd.DataFrame({
    "metric": [k.replace("_mean", "") for k in mean_rows],
    "mean":   list(mean_rows.values()),
    "std":    [std_rows.get(k.replace("_mean", "_std"), 0.0) for k in mean_rows],
})
df_agg = df_agg.set_index("metric").sort_index()
display(df_agg.style.format("{:.4f}"))

# Per-metric score bars
if eval_results:
    print("Deterministic scores:")
    for metric, value in sorted(result_detail.deterministic_scores.items()):
        bar = "#" * int(value * 30)
        print(f"  {metric:<30} {value:.4f}  {bar}")

    if result_detail.llm_judge_scores:
        print("\nLLM judge scores:")
        for metric, value in sorted(result_detail.llm_judge_scores.items()):
            bar = "#" * int(value * 30)
            print(f"  {metric:<30} {value:.4f}  {bar}")

# Rubric breakdown with reasoning (only populated when USE_LLM_JUDGE=True)
if eval_results and result_detail.rubric_breakdown:
    print("Rubric breakdown:")
    for dim, info in sorted(result_detail.rubric_breakdown.items()):
        print(f"\n[{dim}]  score = {info['score']:.2f}")
        print(f"  {info['reasoning']}")
elif USE_LLM_JUDGE:
    print("No rubric breakdown available.")
else:
    print("LLM judge was disabled — no rubric breakdown. Set JUDGE_MODEL_ID to enable.")

def build_comparison_df(eval_dir: Path, manifests: list[EvalRunManifest]) -> pd.DataFrame:
    """Load results for each run and build a comparison DataFrame (one row per run)."""
    rows = []
    for m in manifests:
        try:
            _, results = load_eval_run(m.run_id, eval_dir)
        except Exception:
            continue
        if not results:
            continue
        overall = [r.overall_score for r in results]
        hard = [r.deterministic_scores.get("hard_constraint_ratio", 0.0) for r in results]
        soft = [r.deterministic_scores.get("soft_constraint_score", 0.0) for r in results]
        budget = [r.deterministic_scores.get("budget_adherence", 0.0) for r in results]
        metric_vers = {r.metric_version for r in results}
        rows.append({
            "run_id":               m.run_id,
            "created_at":           m.created_at[:19],
            "compressor":           m.compressor_type,
            "agent_mode":           m.agent_mode,
            "metric_version":       ", ".join(sorted(metric_vers)),
            "n_episodes":           m.n_episodes,
            "overall_mean":         sum(overall) / len(overall),
            "hard_constraint_mean": sum(hard) / len(hard),
            "soft_constraint_mean": sum(soft) / len(soft),
            "budget_adherence_mean":sum(budget) / len(budget),
            "det_only":             m.deterministic_only,
        })
    return pd.DataFrame(rows).sort_values("overall_mean", ascending=False)


# Compare up to the 5 most recent runs
compare_manifests = all_manifests[:5]
if compare_manifests:
    df_compare = build_comparison_df(EVAL_DIR, compare_manifests)
    display(df_compare.style.format({
        "overall_mean": "{:.4f}",
        "hard_constraint_mean": "{:.4f}",
        "soft_constraint_mean": "{:.4f}",
        "budget_adherence_mean": "{:.4f}",
    }))
else:
    print("No previous runs to compare.")

